// Synthetic calibration repository.
const journal = new Map();
export function send(id, payload, transport) { journal.set(id, payload); return transport(id, payload); }
export function receipt(id) { journal.delete(id); }
export function retry(transport) { for (const [id, payload] of journal) transport(id, payload); }

